_X544_NS = {"__name__": "x544_selector_branch"}
_MOON_NS = {"__name__": "moon_selector_branch"}
exec(
    compile(
        base64.b85decode(_X544_SOURCE_B85.encode("ascii")).decode("utf-8"),
        "x544_selector_branch.py",
        "exec",
    ),
    _X544_NS,
    _X544_NS,
)
exec(
    compile(
        base64.b85decode(_MOON_SOURCE_B85.encode("ascii")).decode("utf-8"),
        "moon_selector_branch.py",
        "exec",
    ),
    _MOON_NS,
    _MOON_NS,
)

_SELECTED_ROUTE = None
_SELECTOR_TELEMETRY = {
    "selected_route": None,
    "opening_disagreement": 0,
    "pasture_opening": False,
}


def _selector_get(value, key, default=None):
    if isinstance(value, dict):
        return value.get(key, default)
    return getattr(value, key, default)


def _selector_step(obs):
    value = _selector_get(obs, "step", None)
    if value is not None:
        return int(value or 0)
    return int(_selector_get(obs, "day", 0) or 0) * 24 + int(
        _selector_get(obs, "hour", 0) or 0
    )


def _selector_opponent_has_opening_pasture(obs):
    player = int(_selector_get(obs, "player", 0) or 0)
    farms = list(_selector_get(obs, "farms", []) or [])
    opponent = 1 - player
    if opponent < 0 or opponent >= len(farms):
        return False
    tiles = _selector_get(farms[opponent], "tiles", []) or []
    for row in tiles:
        for tile in row or []:
            if isinstance(tile, dict) and tile.get("kind") == "PASTURE":
                return True
    return False


def _selector_call(namespace, obs, configuration):
    branch = namespace["agent"]
    code = getattr(branch, "__code__", None)
    if code is not None and code.co_argcount >= 2:
        return branch(obs, configuration)
    return branch(obs)


def agent(obs, configuration=None):
    global _SELECTED_ROUTE
    step = _selector_step(obs)
    if step == 0:
        _SELECTED_ROUTE = None
        # Moon needs a step-0 call to initialize its compatible route state.
        # Run that discarded branch on copies and restore Python's global RNG:
        # local agents share a process, so shadow initialization must not alter
        # the live observation/configuration or an opponent's random stream.
        moon_obs = _selector_copy.deepcopy(obs)
        moon_configuration = _selector_copy.deepcopy(configuration)
        x544_action = _selector_call(_X544_NS, obs, configuration)
        random_state = _selector_random.getstate()
        try:
            moon_action = _selector_call(_MOON_NS, moon_obs, moon_configuration)
        finally:
            _selector_random.setstate(random_state)
        if x544_action != moon_action:
            _SELECTOR_TELEMETRY["opening_disagreement"] += 1
        return x544_action

    if _SELECTED_ROUTE is None:
        pasture_opening = _selector_opponent_has_opening_pasture(obs)
        _SELECTED_ROUTE = "moon" if pasture_opening else "x544"
        _SELECTOR_TELEMETRY["selected_route"] = _SELECTED_ROUTE
        _SELECTOR_TELEMETRY["pasture_opening"] = pasture_opening

    namespace = _MOON_NS if _SELECTED_ROUTE == "moon" else _X544_NS
    return _selector_call(namespace, obs, configuration)


agent.telemetry = _SELECTOR_TELEMETRY
__version__ = "H22-early-public-family-selector-v1"

# kaggle-environments selects the last callable inserted into module globals.
kaggle_entrypoint = agent

# Generated H21 pre-EOD routing overlay. Selected unit indexes use farmer=0,
# hand_0=1, ... and are intentionally fixed for a causal route-cost screen.
import copy as _h21_copy
from collections import deque as _h21_deque

_H21_BASE_AGENT = agent
_H21_ACTORS = (1, 2)
_H21_START_STEP = 689
_H21_MIN_TOTAL = 90
_H21_ROUTE = 'moon'
_H21_ACTIVE = {0: False, 1: False}
_H21_TELEMETRY = {
    "triggered": False,
    "trigger_total": None,
    "required_route": _H21_ROUTE,
    "route_moves": 0,
    "drops": 0,
    "sold": {},
}


def _h21_get(value, key, default=None):
    if isinstance(value, dict):
        return value.get(key, default)
    return getattr(value, key, default)


def _h21_access(size):
    half = size // 2
    return {(half - 1, half - 1), (half, half - 1), (half - 1, half), (half, half)}


def _h21_move(position, goals, tiles):
    start = tuple(map(int, position[:2]))
    if start in goals:
        return ["PASS"]
    size = len(tiles)
    queue = _h21_deque([start])
    first = {start: None}
    directions = (("NORTH", 0, -1), ("SOUTH", 0, 1), ("WEST", -1, 0), ("EAST", 1, 0))
    while queue:
        x, y = queue.popleft()
        for operation, dx, dy in directions:
            cell = (x + dx, y + dy)
            if cell in first or not (0 <= cell[0] < size and 0 <= cell[1] < size):
                continue
            if tiles[cell[1]][cell[0]] == "LOCKED":
                continue
            first[cell] = operation if (x, y) == start else first[(x, y)]
            if cell in goals:
                return [first[cell]]
            queue.append(cell)
    return ["PASS"]


def _h21_add_sales(action, inventory):
    totals = {}
    for raw in action.get("market") or []:
        if len(raw) >= 3 and raw[0] == "SELL":
            totals[str(raw[1])] = totals.get(str(raw[1]), 0) + max(0, int(raw[2] or 0))
    for item, raw_count in dict(inventory or {}).items():
        count = max(0, int(raw_count or 0))
        if count:
            totals[str(item)] = totals.get(str(item), 0) + count
            sold = _H21_TELEMETRY["sold"]
            sold[str(item)] = sold.get(str(item), 0) + count
    retained = [list(raw) for raw in action.get("market") or [] if not (len(raw) >= 3 and raw[0] == "SELL")]
    retained.extend(["SELL", item, count] for item, count in totals.items() if count > 0)
    action["market"] = retained[:10]


def agent(obs, configuration=None):
    action = _h21_copy.deepcopy(_H21_BASE_AGENT(obs, configuration))
    step = int(_h21_get(obs, "step", 0) or 0)
    seat = int(_h21_get(obs, "player", 0) or 0)
    if step == 0:
        _H21_ACTIVE[seat] = False
    if step < _H21_START_STEP or step > 695:
        return action
    farms = list(_h21_get(obs, "farms", []) or [])
    if seat >= len(farms):
        return action
    farm = farms[seat]
    private = _h21_get(obs, "private", {}) or {}
    positions = [_h21_get(farm, "farmer"), *list(_h21_get(farm, "hands", []) or [])]
    inventories = list(_h21_get(private, "inventories", []) or [])
    inventories.extend({} for _ in range(len(positions) - len(inventories)))
    if step == _H21_START_STEP:
        shed = dict(_h21_get(private, "shed", {}) or {})
        total = sum(max(0, int(value or 0)) for value in shed.values())
        total += sum(
            max(0, int(value or 0))
            for inventory in inventories
            for value in dict(inventory or {}).values()
        )
        route_matches = _H21_ROUTE is None or globals().get("_SELECTED_ROUTE") == _H21_ROUTE
        _H21_ACTIVE[seat] = route_matches and total >= _H21_MIN_TOTAL
        _H21_TELEMETRY["triggered"] = _H21_ACTIVE[seat]
        _H21_TELEMETRY["trigger_total"] = total
    if not _H21_ACTIVE[seat]:
        return action
    tiles = list(_h21_get(farm, "tiles", []) or [])
    goals = _h21_access(len(tiles))
    hands = action.get("hands", []) or []
    orders = [action.get("farmer") or ["PASS"], *hands]
    for index in _H21_ACTORS:
        if index >= len(positions) or index >= len(inventories) or index >= len(orders):
            continue
        inventory = dict(inventories[index] or {})
        if not any(int(value or 0) > 0 for value in inventory.values()):
            continue
        if tuple(map(int, positions[index][:2])) in goals:
            orders[index] = ["DROP"]
            _h21_add_sales(action, inventory)
            _H21_TELEMETRY["drops"] += 1
        else:
            orders[index] = _h21_move(positions[index], goals, tiles)
            _H21_TELEMETRY["route_moves"] += 1
    action["farmer"] = orders[0]
    action["hands"] = orders[1:]
    return action


agent.telemetry = _H21_TELEMETRY
__version__ = "H21-terminal-route-moon-p90-1-2"
# The selector source already contains ``kaggle_entrypoint``. Reassigning that
# existing dict key does not move it after helpers for Kaggle's insertion-order
# loader, so H21 needs a fresh final alias name.
h21_kaggle_entrypoint = agent


# Generated market-timing experiment: conserve quantities while moving only
# an already scheduled WHEAT/FERTILIZER sale a bounded number of turns earlier.
import copy as _mt_copy

_MT_BASE_AGENT = agent
_MT_ITEMS = ('FERTILIZER',)
_MT_CAPS = {'WHEAT': 10, 'FERTILIZER': 10}
_MT_START = 120
_MT_STOP = 715
_MT_LEAD_X544 = 1
_MT_LEAD_MOON = 2
_MT_MOON_WINDOW_LEAD = 3
_MT_MOON_WINDOW_START = 480
_MT_MOON_WINDOW_STOP = 715
_MT_OPENING = 'keep'
_MT_DEBT = {0: {}, 1: {}}
_MT_LAST = {0: -1, 1: -1}
_MT_TELEMETRY = {
    "advanced": {},
    "repaid": {},
    "opening": _MT_OPENING,
    "lead_x544": _MT_LEAD_X544,
    "lead_moon": _MT_LEAD_MOON,
    "moon_window_lead": _MT_MOON_WINDOW_LEAD,
    "moon_window": [_MT_MOON_WINDOW_START, _MT_MOON_WINDOW_STOP],
}


def _mt_trace():
    if globals().get("_SELECTED_ROUTE") == "moon":
        return globals().get("_MOON_NS", {}).get("_ACTIONS", [])
    nested = globals().get("_X544_NS", {}).get("_X540_NS", {})
    return nested.get("_ACTIONS", [])


def _mt_lead(step):
    if globals().get("_SELECTED_ROUTE") != "moon":
        return _MT_LEAD_X544
    if (_MT_MOON_WINDOW_LEAD is not None and
            _MT_MOON_WINDOW_START <= step < _MT_MOON_WINDOW_STOP):
        return _MT_MOON_WINDOW_LEAD
    return _MT_LEAD_MOON


def _mt_repay(action, debt):
    if not debt:
        return action
    out = []
    for raw in action.get("market") or []:
        order = list(raw)
        if len(order) >= 3 and order[0] == "SELL" and debt.get(order[1], 0) > 0:
            item = str(order[1])
            quantity = max(0, int(order[2] or 0))
            reduction = min(quantity, int(debt[item]))
            quantity -= reduction
            debt[item] -= reduction
            _MT_TELEMETRY["repaid"][item] = _MT_TELEMETRY["repaid"].get(item, 0) + reduction
            if quantity <= 0:
                continue
            order[2] = quantity
        out.append(order)
    action["market"] = out
    return action


def _mt_advance(action, obs, step, schedule):
    if not _MT_ITEMS or step < _MT_START or step >= _MT_STOP:
        return action
    trace = _mt_trace()
    future_step = step + _mt_lead(step)
    if future_step >= len(trace):
        return action
    future = {}
    for raw in trace[future_step].get("market") or []:
        if len(raw) >= 3 and raw[0] == "SELL" and raw[1] in _MT_ITEMS:
            item = str(raw[1])
            future[item] = future.get(item, 0) + max(0, int(raw[2] or 0))
    market = [list(raw) for raw in action.get("market") or []]
    if not future or len(market) >= 10:
        return action
    committed = {}
    for raw in market:
        if len(raw) >= 3 and raw[0] == "SELL":
            item = str(raw[1])
            committed[item] = committed.get(item, 0) + max(0, int(raw[2] or 0))
    private = obs.get("private") or {}
    shed = private.get("shed") or {}
    for item in _MT_ITEMS:
        if len(market) >= 10:
            break
        available = max(0, int(shed.get(item, 0) or 0) - committed.get(item, 0))
        quantity = min(future.get(item, 0), int(_MT_CAPS.get(item, 0)), available)
        if quantity <= 0:
            continue
        market.append(["SELL", item, quantity])
        due = schedule.setdefault(future_step, {})
        due[item] = due.get(item, 0) + quantity
        _MT_TELEMETRY["advanced"][item] = _MT_TELEMETRY["advanced"].get(item, 0) + quantity
    action["market"] = market
    return action


def _mt_opening(action, step):
    if step != 0 or _MT_OPENING == "keep":
        return action
    wanted = 5 if _MT_OPENING == "feed5_first" else 6
    market = [list(raw) for raw in action.get("market") or []]
    rest = [raw for raw in market if not (
        len(raw) >= 3 and raw[0] == "BUY_PRODUCT" and raw[1] == "WHEAT"
    )]
    action["market"] = [["BUY_PRODUCT", "WHEAT", wanted], *rest][:10]
    return action


def agent(obs, configuration=None):
    action = _mt_copy.deepcopy(_MT_BASE_AGENT(obs, configuration))
    try:
        step = int(obs.get("step", 0) or 0)
        seat = 1 if int(obs.get("player", 0) or 0) == 1 else 0
        if step == 0 or step <= _MT_LAST[seat]:
            _MT_DEBT[seat] = {}
        _MT_LAST[seat] = step
        schedule = _MT_DEBT[seat]
        due = schedule.pop(step, {})
        action = _mt_repay(action, due)
        if due:
            carry = schedule.setdefault(step + 1, {})
            for item, quantity in due.items():
                if quantity > 0:
                    carry[item] = carry.get(item, 0) + quantity
        action = _mt_opening(action, step)
        return _mt_advance(action, obs, step, schedule)
    except Exception:
        return action


agent.telemetry = _MT_TELEMETRY
__version__ = "market-timing-n29_routelead_m2_m3_late"
market_timing_kaggle_entrypoint = agent
